create or replace function app_private.support_hours_snapshot(p_at timestamptz default now())returns jsonb language plpgsql stable security definer set search_path='' as $$declare config app_private.support_hours%rowtype;cairo_clock timestamp:=p_at at time zone'Africa/Cairo';begin select * into config from app_private.support_hours where singleton;return jsonb_build_object('staffed_hours_configured',jsonb_array_length(config.weekly_intervals)>0,'staffed_hours',config.weekly_intervals,'staffed_hours_open',case when jsonb_array_length(config.weekly_intervals)>0 then exists(select 1 from jsonb_array_elements(config.weekly_intervals)i where(i->>'weekday')::integer=extract(isodow from cairo_clock)::integer and cairo_clock::time>=(i->>'start_local')::time and cairo_clock::time<(i->>'end_local')::time)end,'staffed_target_minutes',config.response_target_minutes);end$$;
